INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f985b5b2-5151-44a9-b469-b0164cc71a89', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$101. óra: Feladatmegoldás$q$, $q$Összetett kerületszámítási és kerítésszámítási szöveges feladatok.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "1818aca9-7f4c-4f8d-b712-71e8e6b06dfe", "text": "Egy téglalap alakú kert hossza 20 m, szélessége 15 m. Hány méter kerítés övezi a kertet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "b34dab54-b256-4195-9977-41a345d99908", "text": "Hány méter kerítés kell a 20m x 15m-es kerthez, ha hagyunk egy 2 m-es kaput? (70 - 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "68"}, {"id": "9b2e6dff-f298-4095-baa2-01549e812536", "text": "Egy négyzet alakú pálya kerülete 100 m. Hány méter hosszú a pálya egy oldala? (100 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "ea31d661-569c-4962-8210-d120341a6d35", "text": "Ha a téglalap kerülete 30 cm, és egyik oldala 5 cm, mekkora a másik oldal? (15 - 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "99d30123-c8e1-4f85-ba32-18010aa3fcb0", "text": "A sokszögek kerületét mindig hosszúság-mértékegységben (m, cm, mm) adjuk meg.", "type": "true-false", "options": [{"id": "c02efc6f-2155-43be-a68a-f6ce61deae4c", "text": "Igaz", "isCorrect": true}, {"id": "114d0301-c512-468e-8f52-30fa43bf0753", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "27127351-056e-44aa-adc6-503704e12d01", "text": "Mennyi a 10 cm oldalú szabályos hatszög kerülete?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "647780d5-e496-48ae-b406-9577e8783f4a", "text": "A kerületszámításos feladatoknál az oldalaknak azonos mértékegységben kell lenniük.", "type": "true-false", "options": [{"id": "97875326-ab32-4e03-a9bd-c15f49cb3952", "text": "Igaz", "isCorrect": true}, {"id": "162ff7fc-8700-43b0-b339-e743d14998d2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1310e9d6-9489-4365-9676-ccf4219b3108', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$102. óra: A terület és a térfogat mérése$q$, $q$A terület és térfogat mértékegységei, lefedés, egységkockák, átváltások.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "faac8a86-a014-4f2e-a945-369dedfd4df1", "text": "Mi a terület alapvető mértékegysége az SI-ben?", "type": "multiple-choice", "options": [{"id": "eb8a8a0c-085e-4c53-8730-4667dd34081e", "text": "Négyzetméter (m²)", "isCorrect": true}, {"id": "36e0227a-c40f-4905-9bf2-320bed7ac41d", "text": "Méter (m)", "isCorrect": false}, {"id": "3bd4878c-ba53-4cba-ba27-8bd28e44153d", "text": "Köbméter (m³)", "isCorrect": false}, {"id": "a62527d0-423e-4da4-a877-5b42ce39c4ae", "text": "Liter (l)", "isCorrect": false}], "timeLimit": 15}, {"id": "1c09d5ea-e0dc-4e82-b837-a350d0b3cb7e", "text": "Hány cm² 1 dm²? (10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "192f3ab5-d826-416c-a46e-1cc1f5a8f877", "text": "Hány dm² 1 m²? (10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "838d0465-67ce-4246-9292-d8fd2c5586c8", "text": "Hány dm³ 1 m³? (10 * 10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "734e9767-100f-4241-bf2c-28ee2031297e", "text": "1 liter űrtartalom pontosan 1 köbdeciméternek (1 dm³) felel meg.", "type": "true-false", "options": [{"id": "a6f13c4d-493c-432d-8359-25b9afadbcea", "text": "Igaz", "isCorrect": true}, {"id": "f532cae3-adf6-4683-9618-b10a505fcb5a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c9d9ad3c-f14a-486c-86f6-da2e76ad9107", "text": "Hány cm³ 1 dm³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "aee22d51-5c03-486d-a65c-cf188d40fb76", "text": "A terület mértékegységei között a szomszédos váltószám 100 (területnél 10²).", "type": "true-false", "options": [{"id": "5191ea86-0946-4fdc-992c-5066ee80a9b3", "text": "Igaz", "isCorrect": true}, {"id": "5592fcf9-0100-437b-bc54-8ebca50bde1e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('321349d0-0bcf-4c81-899c-ba7989ee53b8', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$103. óra: Gyakorlóóra. A terület és a térfogat mérése$q$, $q$Terület- és térfogat-mértékegységek gyakorlása digitális feladatlapokon.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "2e519b6a-540f-4a61-ae07-6782d0fdaf1d", "text": "Hány mm² 1 cm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "022f871b-bb3c-4c2f-a979-dc32ccbb49a7", "text": "Hány cm³ 2 liter? (2 dm³ = 2000 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "60a9b87b-436b-4e26-ac20-390b34ef112e", "text": "Hány m² 500 dm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "35350106-1785-466c-91d1-57b71bb6f66c", "text": "Hány litere felel meg 3,5 dm³ víznek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3.5"}, {"id": "90552285-f9e1-4cab-8d13-1dbf7e0dc406", "text": "A térfogat mértékegységei között a szomszédos váltószám 1000 (10³).", "type": "true-false", "options": [{"id": "b8f619a2-2505-4ffe-ad9a-791c01498afd", "text": "Igaz", "isCorrect": true}, {"id": "82c6a391-df7f-4b1a-a6c3-5f1680750bc0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5e8a2e0e-b4c6-4888-b131-94e1aa991038", "text": "Hány dl 1 liter?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "3c745d14-d1b6-44d1-8604-353f1cca7359", "text": "Hány ml 1 dm³ (1 liter)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b03c575c-4962-4dc9-a126-ea12fd7362f6', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$104. óra: A sokszögek területe$q$, $q$Négyzet, téglalap és derékszögű háromszög területe (T).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "a5b9e6d2-6f4a-406a-9969-ccdaca1d90c5", "text": "Mi a téglalap területének képlete (a és b oldallal)?", "type": "multiple-choice", "options": [{"id": "a3ad4785-2334-4895-8dae-49ecbac3f469", "text": "T = a * b", "isCorrect": true}, {"id": "c23f028b-393f-4808-bfd8-0ce9dfab072b", "text": "T = 2 * (a + b)", "isCorrect": false}, {"id": "15af38c9-3c3c-446c-a6b4-a07ee7588f4b", "text": "T = a + b", "isCorrect": false}, {"id": "b5c50b72-1efc-4220-9a8b-b1d01dff7709", "text": "T = a * a * a", "isCorrect": false}], "timeLimit": 15}, {"id": "0268f0ca-0612-436e-8740-a0ebce1129a4", "text": "Mi a négyzet területének képlete ('a' oldallal)?", "type": "multiple-choice", "options": [{"id": "d02503c8-f779-4f50-8005-b902e80f25fd", "text": "T = a * a (a²)", "isCorrect": true}, {"id": "f394cc37-813b-4d45-ba57-4868e307d122", "text": "T = 4 * a", "isCorrect": false}, {"id": "d172fd85-adbe-4178-a55d-dfd1910e5d64", "text": "T = 2 * a", "isCorrect": false}, {"id": "266397ab-8744-4a5a-af0e-bb1dd39209f9", "text": "T = a * 10", "isCorrect": false}], "timeLimit": 15}, {"id": "ce0a5295-5688-4e09-a0cb-659ecb599388", "text": "Mennyi a 6 cm és 8 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "bd145365-33f1-4bdd-a66a-ea650c18bbbc", "text": "Mennyi a 5 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "fea85396-2592-4171-aaa4-7aa8ae9e6d08", "text": "Mi a derékszögű háromszög területének képlete (a és b befogókkal)?", "type": "multiple-choice", "options": [{"id": "c65a08ed-a33b-4227-afa5-d36c68f72cfd", "text": "T = (a * b) / 2", "isCorrect": true}, {"id": "1a51951a-16d7-4e44-969a-d3fa9670d77a", "text": "T = a * b", "isCorrect": false}, {"id": "5d693d1e-9e05-44ad-ab77-9a7b01bd167b", "text": "T = a + b", "isCorrect": false}, {"id": "ee9f6f68-1af3-4559-8afc-8e8801571642", "text": "T = 2 * a * b", "isCorrect": false}], "timeLimit": 15}, {"id": "1862be49-6a5c-4098-b5e5-fa0626575d84", "text": "Mennyi a 6 cm és 8 cm befogójú derékszögű háromszög területe? ((6*8)/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "d2b5978c-d3db-4a98-b679-ccf5b1927066", "text": "A derékszögű háromszög területe a két befogójú téglalap területének fele.", "type": "true-false", "options": [{"id": "f4374a37-ebe9-492c-95fa-2a42bec1ee79", "text": "Igaz", "isCorrect": true}, {"id": "86f3782c-c892-4596-9918-6b249adba2f8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c3da44f8-2bc2-4c14-bf3d-b59c001275c7', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$105. óra: Feladatmegoldás$q$, $q$Kerület- és területszámítási feladatok, lakóház és szobapadló tervezése.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "973a8793-4a55-420d-afd0-460593df79d8", "text": "Egy 5 m hosszú és 4 m széles szobába szőnyeget fektetünk. Hány m² a szoba területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "89c53659-edbe-4898-9079-66f97fab92a6", "text": "Ha a parketta ára 5000 Ft/m², mennyibe kerül a 20 m²-es szoba parkettázása?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100000"}, {"id": "e44687ad-4378-46cb-8d7c-f401f5d93c05", "text": "Hány méter szegélylécre van szükség a 5m x 4m-es szobához (kerület)? (2*(5+4))", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "c884deac-26cd-43d1-901a-d253a28c2f24", "text": "Egy négyzet alakú szoba területe 36 m². Hány méter hosszú a szoba egy oldala?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "ed599e39-3fdd-417e-a5de-9d67fb729ec2", "text": "A terület számításához a méreteket azonos mértékegységre kell hozni a szorzás előtt.", "type": "true-false", "options": [{"id": "bacab7a0-cdf9-4475-94f2-f5d3c772372c", "text": "Igaz", "isCorrect": true}, {"id": "b57bfe40-fe74-4c93-889f-b3331f7a693c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5baa9831-a8a1-422d-be1f-1e189c2711bf", "text": "Mennyi a 10 cm és 4 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "b4315c78-3b61-4c7b-bde0-1cfd676b9a10", "text": "A lakástervezésben a m² alapvető fontosságú.", "type": "true-false", "options": [{"id": "617a6a64-d6ea-4ce1-9b51-3ed9bbc06f62", "text": "Igaz", "isCorrect": true}, {"id": "15ddd718-0d85-4f13-b9f7-e4c8cb59b8a0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8a9bb0d5-ce1f-436a-ae0f-ecf32698b244', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$106. óra: Alakzatok a térben$q$, $q$Testek elnevezései (kocka, téglatest, hasáb, piramis), él, lap, csúcs, nézetek (elölnézet, felülnézet, oldalnézet).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "1e2316e9-3dd7-426c-bbca-ee2462b08ab5", "text": "Hány lapja van a téglatestnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "be236e7e-de4e-40d9-a46b-17ec4b20f6a8", "text": "Hány csúcsa van a téglatestnek (és a kockának)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "98302358-c7bc-477f-9ea7-39cacf7cea7e", "text": "Hány éle van a téglatestnek (és a kockának)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "2dfa69a5-3741-404a-abfa-2c8c4ffdb5f0", "text": "A kocka minden lapja egyenlő négyzet.", "type": "true-false", "options": [{"id": "4736f660-d5a1-40e9-90c6-f67fb6f58adb", "text": "Igaz", "isCorrect": true}, {"id": "1a69f29d-73c1-4283-960c-7d590ce55a0f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "564a9832-aba1-4a3c-ba89-9fb277eac616", "text": "Milyen alakúak a téglatest lapjai?", "type": "multiple-choice", "options": [{"id": "36700bdd-b20e-4a1f-a43f-592f16b60b46", "text": "Téglalapok (melyek között négyzet is lehet)", "isCorrect": true}, {"id": "26c8a56c-8b74-453a-a533-65da8c625869", "text": "Háromszögek", "isCorrect": false}, {"id": "129c6e8d-8542-4131-a68d-c3979f192375", "text": "Körök", "isCorrect": false}, {"id": "9999d21e-5dd7-4172-81e8-58a4fd71ac36", "text": "Ötszögek", "isCorrect": false}], "timeLimit": 15}, {"id": "055acea2-f0f6-4232-8b51-107bd7267e6f", "text": "A testek felülről, elölről és oldalról készített 2D vetületei a vetületi képek.", "type": "true-false", "options": [{"id": "9d588b4f-b8f6-46f1-9da1-9d658a076955", "text": "Igaz", "isCorrect": true}, {"id": "34900a34-0d81-4494-995f-9340b340be92", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2386dcb5-5a32-4fc6-9804-42483aa74b55", "text": "Hány lapja van a négyszög alapú gúlának (piramisnak)? (1 alap + 4 oldal)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f83e6d1e-65dd-4633-8512-5fb59329fd6c', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$107. óra: Testek felszíne$q$, $q$Kocka és téglatest felszínének kiszámítása (A vagy F).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "40ad9bc9-a51b-4a3c-a2c3-542a17936306", "text": "Mi a kocka felszínének képlete ('a' éllel)?", "type": "multiple-choice", "options": [{"id": "cead0d1d-4a40-4e4e-9871-c0b10e8a66de", "text": "F = 6 * a * a (6 * a²)", "isCorrect": true}, {"id": "2f1bdef9-b1e3-484c-b1ed-dcdf5874481b", "text": "F = a * a * a", "isCorrect": false}, {"id": "7dffaae9-5eb0-4cde-bfd7-897a35ae97a9", "text": "F = 12 * a", "isCorrect": false}, {"id": "0d8fe4c2-5fa3-492b-bca5-137cd7fd043d", "text": "F = 4 * a²", "isCorrect": false}], "timeLimit": 15}, {"id": "1d4a2bd8-f9b7-4b5e-b9e1-88d0c9c1a165", "text": "Mi a téglatest felszínének képlete (a, b, c élekkel)?", "type": "multiple-choice", "options": [{"id": "83e41238-13c9-4aa5-8027-bede9d7d0352", "text": "F = 2 * (a*b + a*c + b*c)", "isCorrect": true}, {"id": "42d9e344-f70b-4fbb-aaec-c524d0a54b3c", "text": "F = a * b * c", "isCorrect": false}, {"id": "7f37f2e0-d036-4bd0-9ed6-b123d1be8185", "text": "F = 4 * (a + b + c)", "isCorrect": false}, {"id": "30b5b12d-8ca8-4a72-a099-8b775082d785", "text": "F = a*b + c", "isCorrect": false}], "timeLimit": 15}, {"id": "1a942cdf-9e78-4e10-af57-b11be1c6711f", "text": "Mennyi a 3 cm élű kocka felszíne? (6 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "d5133a45-c983-4924-b16d-9e863eee78e5", "text": "Mennyi a 2 cm, 3 cm, 4 cm élű téglatest felszíne? (2*(2*3 + 2*4 + 3*4) = 2*(6+8+12) = 2*26)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "52"}, {"id": "0b74b070-e18f-43c0-b8f5-0acd4e4c31ff", "text": "A felszín a testet határoló lapok területeinek összege.", "type": "true-false", "options": [{"id": "b5777314-59c4-410e-8526-1c535d12139f", "text": "Igaz", "isCorrect": true}, {"id": "eee4fe80-b272-416e-9f95-413e42e350fc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ddace4d5-32ce-421f-bece-dca37479ae5d", "text": "A felszínt mindig terület-mértékegységben (cm², m²) adjuk meg.", "type": "true-false", "options": [{"id": "e0fd3462-9755-41cd-a5fd-840ee4000e1e", "text": "Igaz", "isCorrect": true}, {"id": "bccb6fab-783b-4230-b774-f83f416c2e59", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9884aced-0bbb-41eb-ac27-9eb490954d92", "text": "Mennyi a 10 cm élű kocka felszíne? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "600"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b8829999-8b1d-49b6-890a-28e8ad62cb73', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$108. óra: Gyakorlóóra$q$, $q$Felszínszámítás gyakorlása hálók megrajzolásával és szerkesztőprogrammal.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "cab3268c-2317-436b-abac-bb045309f397", "text": "Hány négyzetből áll a kocka hálója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "7a8715e1-e990-47d7-9bc0-793fb33a0226", "text": "Mennyi a 4 cm élű kocka felszíne? (6 * 16)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "fe080158-52e7-4f99-8d0f-ddbda8cd218d", "text": "Mennyi a 1 m, 2 m, 3 m élű téglatest felszíne? (2*(2+3+6) = 2*11)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "058e10ad-8d9c-4684-8eec-2df4f0b33714", "text": "A test hálójának területe megegyezik a test felszínével.", "type": "true-false", "options": [{"id": "5be8bb7e-bb20-415c-a196-515d9860e771", "text": "Igaz", "isCorrect": true}, {"id": "57bd4977-b6f7-4a93-b082-142490cf5340", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "00797c72-8914-403d-b23a-b812d1e7c9de", "text": "Mennyi a 5 cm élű kocka felszíne? (6 * 25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "a35e1986-c4f4-48fa-81d1-0288d75da996", "text": "Dinamikus szerkesztőprogrammal a testek hálója kiteríthető és összehajtható.", "type": "true-false", "options": [{"id": "ea968c5e-5a7e-4c30-ab78-7985c7ccce1d", "text": "Igaz", "isCorrect": true}, {"id": "ca73acb7-dc3c-4866-abeb-bdec83a08d3e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fa3c6a59-f5a7-4a35-9939-e574f1156ab4", "text": "A téglatest szemközti lapjai egyenlő területűek.", "type": "true-false", "options": [{"id": "c87a0829-35cc-44d5-ae5e-239faeb58c5a", "text": "Igaz", "isCorrect": true}, {"id": "9e3fd664-277b-47e7-a354-fd1f62bbaf0f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('64230fbf-d298-4651-9690-d3fc2d7f6a60', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$109. óra: Felszínszámítással kapcsolatos gyakorlati feladatok$q$, $q$Dobozok lefestése, csomagolópapír szükséglet kiszámítása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "71ae09ed-8a12-405c-a7bc-dc3bb060b9e3", "text": "Egy 10 cm x 20 cm x 30 cm-es téglatest dobozt befestünk. Hány cm² felületet kell lefesteni? (2*(200+300+600) = 2*1100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2200"}, {"id": "48130144-c9e4-40a5-bcb8-a0a17ce8b68b", "text": "Hány cm² csomagolópapír kell egy 5 cm élű kocka alakú ajándék becsomagolásához (ráhagyás nélkül)? (6 * 25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "6e19f593-55a2-402d-b9a8-f6b97ccf1d38", "text": "Ha a festékből 1 m²-re 200 g kell, hány gramm festék kell 5 m² felszínre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "c8dba3aa-0266-4dd9-b34f-d765e3fc6c27", "text": "Csomagoláskor a veszteség és az átfedés miatt érdemes a kiszámított felszínnél kb. 10-20%-kal több papírral számolni.", "type": "true-false", "options": [{"id": "e73dc88a-9dc3-4caa-afa3-d7b1264dc5cc", "text": "Igaz", "isCorrect": true}, {"id": "fde87818-36df-4ed8-a391-f3a37591ff4c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e6e88c00-c369-4018-a501-16a307df6ecd", "text": "Mennyi a 2 cm élű kocka felszíne? (6 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "00f6cb4e-e86d-40ba-9805-b12da4aa817a", "text": "A dobozok tervezésénél az anyagszükségletet a felszín határozza meg.", "type": "true-false", "options": [{"id": "35e28b6f-f3a5-4172-b073-9b0920d85dd5", "text": "Igaz", "isCorrect": true}, {"id": "1afc9e7b-d612-4bac-95e7-f3fe6f43c531", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dde547fe-9cac-4b1e-b5b0-4811d8fe4522", "text": "Mennyi a 1 cm élű kocka felszíne?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('17431a60-a504-47eb-a50b-f585430da2cf', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$110. óra: Testek térfogata$q$, $q$Téglatest és kocka térfogatának (V) kiszámítása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "a2a96e45-a435-405c-9562-1e20b831ad5b", "text": "Mi a kocka térfogatának képlete ('a' éllel)?", "type": "multiple-choice", "options": [{"id": "1487ab74-d3a4-4b99-a4d9-d0efa58924ed", "text": "V = a * a * a (a³)", "isCorrect": true}, {"id": "9b6bbc8b-608b-47df-b009-5b5699dc2d2e", "text": "V = 6 * a²", "isCorrect": false}, {"id": "7f1c3b63-dfbe-418d-a381-0e068cfe7dc7", "text": "V = 12 * a", "isCorrect": false}, {"id": "cf1c311a-f82f-46f7-8dab-3a3a5830247d", "text": "V = a + a + a", "isCorrect": false}], "timeLimit": 15}, {"id": "b042ac8d-f221-43af-9466-1ad99e74a10d", "text": "Mi a téglatest térfogatának képlete (a, b, c élekkel)?", "type": "multiple-choice", "options": [{"id": "b730fdb4-149b-4381-86bd-1de617b741e3", "text": "V = a * b * c", "isCorrect": true}, {"id": "f0906658-6480-46fb-977c-417319609b24", "text": "V = 2 * (a+b+c)", "isCorrect": false}, {"id": "d6cd13d0-b9fa-466f-a9c6-1aa1f721f535", "text": "V = a * b", "isCorrect": false}, {"id": "a38abace-ca01-426e-be48-4a4a60c257e2", "text": "V = a + b + c", "isCorrect": false}], "timeLimit": 15}, {"id": "6b983710-b94a-4869-bb40-2602c953acb6", "text": "Mennyi a 3 cm élű kocka térfogata? (3 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "4f7ea88a-1bd4-424b-b6d9-ff760b9607e8", "text": "Mennyi a 2 cm, 4 cm, 5 cm élű téglatest térfogata? (2 * 4 * 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "b40cb93a-d333-4a3c-97e8-191f0439d625", "text": "A térfogatot mindig köbmértékegységben (cm³, m³, dm³) vagy űrmértékben (liter, dl) adjuk meg.", "type": "true-false", "options": [{"id": "a1da0a7a-98f3-46fc-bf68-d4aa09e58f46", "text": "Igaz", "isCorrect": true}, {"id": "4e6a30ea-91cb-4e0f-9cc1-e61036ce29c5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "21ecbb30-aab8-4f92-92eb-53f6956111b4", "text": "Mennyi a 4 cm élű kocka térfogata? (4 * 4 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "290f1eae-3477-4699-b767-07836806541b", "text": "Mennyi a 10 cm élű kocka térfogata cm³-ben? (1000 cm³ = 1 liter)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;